import numpy as np
z = np.zeros((4, 4))
M = np.zeros((2, 4, 4))
U = np.full_like(z, np.nan)
def _probe(f):
    try:
        f(z, z, M, U, 1.0, (4.0, 4.0))
    except ValueError:
        return 1.0
    except Exception:
        return 2.0
    return 0.0
assert np.allclose(_probe(pfc_modified_energy), target)

